insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Answer with exactly SQL: <<query>> where query is a complete SQL SELECT statement. Use ONLY the exact table and column names from the schema as provided. Do NOT use table aliases or AS clauses. Reference columns as table.column. Keep the query concise and directly answer the question.");

